          "body": "丹尼尔·卡尼曼的前景理论指出，人们对损失的敏感度远高于对收益的敏感度。当物价上涨时，<b>损失厌恶</b>使得消费者对支出增加的感受被放大，即使工资有所增长，心理上的“损失”仍占主导。此外，<b>可得性启发</b>让人们更容易回忆起近期不愉快的购物经历，而忽视整体经济统计。因此，民调中的“恶化”更多是心理账本上的亏损，而非客观收入的全面下降。",
