          "body": "乌尔里希·贝克的风险社会理论认为，现代社会的风险往往由制度性决策产生，并呈现不均衡分布。强降雨本身是自然现象，但<b>风险</b>的放大与基础设施投入、应急响应能力、社会脆弱性密切相关。在韩国庆尚南道，尽管经济发达，但山区地形和快速城市化可能加剧局部洪涝，而低收入社区往往缺乏充足的防灾资源，导致<b>风险</b>的“阶级化”。因此，灾害不仅是天灾，更是社会制度与准备程度的试金石。",
          "aha": "暴雨是自然的，但伤亡数字却是社会的，每一次灾难都在拷问我们的预防与公平。"
